RSpec.describe Invoices::OperationCoordinator, committed_data: true do
  it "keeps the invoice change committed and leaves the commit row for the worker when inline delivery fails" do
    company = create(:company)
    invoice = create(:invoice, company:)
    prepared = Invoices::ReservationOutcome.new(state: "prepared", conflicts: [], counts: {})
    adapter = RecordingReservationAdapter.new(
      prepare: prepared,
      commit: ->(_request) { raise StandardError, "reservation store unreachable" },
      abort: Invoices::ReservationOutcome.new(state: "aborted", conflicts: [], counts: {})
    )
    request = Invoices::ReservationRequest.new(
      company_id: company.id,
      invoice_id: invoice.id,
      operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation,
      disposition: "active",
      entries: [11, 12]
    )
    holding = { entry_ids: [11, 12], disposition: "active" }

    # "After the invoice transaction commits, deliver the settlement row once, inline, through
    # `DeliverInvoiceOperationJob.perform_now(outbox_item_id)`. A failed inline delivery leaves the row for the worker."
    expect do
      ApplicationRecord.transaction do
        invoice.update!(reference: "inline-fail")
        described_class.new(reservations: adapter).call(request, holding:)
      end
    end.not_to raise_error

    expect(invoice.reload.reference).to eq("inline-fail")
    intent = InvoiceOperationIntent.find_by!(company_id: company.id, operation_id: request.operation_id)
    expect(intent.state).to eq("committed")

    rows = InvoiceOperationOutboxItem.where(company_id: company.id, operation_id: request.operation_id)
    expect(rows.pluck(:kind)).to eq(["commit"])
    commit_row = rows.first
    expect(commit_row.delivered_at).to be_nil
    expect(commit_row.attempts).to eq(1)
    # One prepare, then exactly one inline commit attempt.
    expect(adapter.requests.size).to eq(2)
  end
end

