RSpec.describe Invoices::OperationCoordinator, committed_data: true do
  def coordinator_order_outcome(state)
    Invoices::ReservationOutcome.new(state:, conflicts: [], counts: {})
  end

  def coordinator_order_request(invoice)
    Invoices::ReservationRequest.new(
      company_id: invoice.company_id, invoice_id: invoice.id, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [501]
    )
  end

  def coordinator_order_adapter(prepare:, commit: coordinator_order_outcome("committed"))
    RecordingReservationAdapter.new(prepare:, commit:, abort: coordinator_order_outcome("aborted"))
  end

  def coordinator_order_rows(request)
    InvoiceOperationOutboxItem.where(company_id: request.company_id, operation_id: request.operation_id)
  end

  def coordinator_order_intent(request)
    InvoiceOperationIntent.find_by!(company_id: request.company_id, operation_id: request.operation_id)
  end

  def coordinator_order_save(adapter, request)
    ApplicationRecord.transaction do
      described_class.new(reservations: adapter).call(request, holding: { entry_ids: [501], disposition: "active" })
    end
  end

  it "has the pending intent committed and visible to another connection while prepare runs" do
    invoice = create(:invoice)
    request = coordinator_order_request(invoice)
    seen_state = nil
    adapter = coordinator_order_adapter(prepare: lambda { |_received|
      committed_data_thread do
        seen_state = InvoiceOperationIntent.where(company_id: request.company_id, operation_id: request.operation_id).pick(:state)
      end.join
      coordinator_order_outcome("prepared")
    })

    coordinator_order_save(adapter, request)

    expect(seen_state).to eq("pending")
  end

  it "keeps the commit row and holding invisible to another connection until the invoice transaction commits" do
    invoice = create(:invoice)
    request = coordinator_order_request(invoice)
    seen_before_commit = nil

    ApplicationRecord.transaction do
      described_class.new(reservations: coordinator_order_adapter(prepare: coordinator_order_outcome("prepared")))
        .call(request, holding: { entry_ids: [501], disposition: "active" })
      committed_data_thread do
        seen_before_commit = [
          coordinator_order_rows(request).count,
          InvoiceEntryHolding.where(company_id: request.company_id, invoice_id: request.invoice_id).count,
          coordinator_order_intent(request).state
        ]
      end.join
    end

    expect(seen_before_commit).to eq([0, 0, "pending"])
    expect(coordinator_order_rows(request).pluck(:kind)).to eq(["commit"])
  end

  it "records failed with one abort row when prepare answers retryable" do
    request = coordinator_order_request(create(:invoice))

    expect { coordinator_order_save(coordinator_order_adapter(prepare: coordinator_order_outcome("retryable")), request) }
      .to raise_error(Invoices::OperationErrors::PrepareRetryable)

    expect(coordinator_order_intent(request).state).to eq("failed")
    expect(coordinator_order_rows(request).pluck(:kind)).to eq(["abort"])
    expect(coordinator_order_rows(request).first.delivered_at).to be_present
  end

  it "records failed with one abort row when prepare raises" do
    request = coordinator_order_request(create(:invoice))
    adapter = coordinator_order_adapter(prepare: ->(_received) { raise IOError, "store unreachable" })

    expect { coordinator_order_save(adapter, request) }.to raise_error(IOError, "store unreachable")

    expect(coordinator_order_intent(request).state).to eq("failed")
    expect(coordinator_order_rows(request).pluck(:kind)).to eq(["abort"])
  end

  it "never takes the commit path on a terminal committed answer to prepare" do
    request = coordinator_order_request(create(:invoice))

    expect { coordinator_order_save(coordinator_order_adapter(prepare: coordinator_order_outcome("committed")), request) }
      .to raise_error(Invoices::OperationErrors::ReconciliationRequired)

    expect(coordinator_order_rows(request).where(kind: "commit")).to be_empty
    expect(InvoiceEntryHolding.where(company_id: request.company_id, invoice_id: request.invoice_id)).to be_empty
  end

  it "writes no abort row when the intent was already failed elsewhere before the rollback" do
    request = coordinator_order_request(create(:invoice))
    adapter = coordinator_order_adapter(prepare: lambda { |_received|
      committed_data_thread do
        InvoiceOperationIntent.where(company_id: request.company_id, operation_id: request.operation_id)
          .update_all(state: "failed", finished_at: Time.current)
      end.join
      coordinator_order_outcome("refused")
    })

    expect { coordinator_order_save(adapter, request) }.to raise_error(Invoices::OperationErrors::Refused)

    expect(coordinator_order_rows(request)).to be_empty
    expect(coordinator_order_intent(request).state).to eq("failed")
  end

  it "keeps the refusal's conflicts on the raised error" do
    request = coordinator_order_request(create(:invoice))
    refused = Invoices::ReservationOutcome.new(state: "refused", conflicts: [{ entry_id: 501, reason: "billed" }], counts: {})

    expect { coordinator_order_save(coordinator_order_adapter(prepare: refused), request) }
      .to raise_error(Invoices::OperationErrors::Refused) { |error| expect(error.outcome.conflicts).to eq([{ entry_id: 501, reason: "billed" }]) }
  end

  it "refuses to run outside a transaction and writes nothing" do
    request = coordinator_order_request(create(:invoice))
    adapter = coordinator_order_adapter(prepare: coordinator_order_outcome("prepared"))

    expect { described_class.new(reservations: adapter).call(request, holding: { entry_ids: [501], disposition: "active" }) }
      .to raise_error(Invoices::OperationErrors::NoTransaction)

    expect(InvoiceOperationIntent.where(company_id: request.company_id)).to be_empty
    expect(adapter.requests).to be_empty
  end

  it "records the failure of a rolled-back savepoint only after the enclosing transaction ends, before sending abort" do
    request = coordinator_order_request(create(:invoice))
    state_seen_at_abort = nil
    adapter = RecordingReservationAdapter.new(
      prepare: coordinator_order_outcome("refused"),
      commit: coordinator_order_outcome("committed"),
      abort: lambda { |_received|
        committed_data_thread do
          state_seen_at_abort = [coordinator_order_intent(request).state, coordinator_order_rows(request).pluck(:kind)]
        end.join
        coordinator_order_outcome("aborted")
      }
    )

    ApplicationRecord.transaction do
      ApplicationRecord.transaction(requires_new: true) do
        described_class.new(reservations: adapter).call(request, holding: { entry_ids: [501], disposition: "active" })
      rescue Invoices::OperationErrors::Refused
        raise ActiveRecord::Rollback
      end
      expect(adapter.requests.size).to eq(1)
      raise ActiveRecord::Rollback
    end

    expect(state_seen_at_abort).to eq(["failed", ["abort"]])
    expect(coordinator_order_intent(request).state).to eq("failed")
    expect(coordinator_order_rows(request).pluck(:kind)).to eq(["abort"])
    expect(adapter.requests.size).to eq(2)
  end

  it "leaves the intent pending with no abort row, and the caller sees the prepare error, when writing the abort row fails" do
    request = coordinator_order_request(create(:invoice))
    adapter = coordinator_order_adapter(prepare: ->(_received) { raise IOError, "store unreachable" })
    allow(InvoiceOperationOutboxItem).to receive(:record!).and_raise(ActiveRecord::StatementInvalid, "abort row write failed")

    expect { coordinator_order_save(adapter, request) }.to raise_error(IOError, "store unreachable")

    expect(coordinator_order_intent(request).state).to eq("pending")
    expect(coordinator_order_rows(request)).to be_empty

    allow(InvoiceOperationOutboxItem).to receive(:record!).and_call_original
    travel(61.seconds) { RecoverInvoiceOperationIntentsJob.perform_now(reservations: adapter) }

    expect(coordinator_order_intent(request).state).to eq("failed")
    expect(coordinator_order_rows(request).pluck(:kind)).to eq(["abort"])
  end

  it "refuses a request built for another ownership generation before writing an intent" do
    request = Invoices::ReservationRequest.new(
      company_id: 7601, invoice_id: 9601, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation + 1, disposition: "active", entries: [501]
    )
    adapter = coordinator_order_adapter(prepare: coordinator_order_outcome("prepared"))

    expect { coordinator_order_save(adapter, request) }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)

    expect(InvoiceOperationIntent.where(company_id: 7601)).to be_empty
    expect(adapter.requests).to be_empty
  end
end
